<include file="Public:header"/><div class="mainbox">	<div id="nav" class="mainnav_title">		<ul>			<a href="{pigcms{:U('score_package')}" class="on">积分套餐列表</a>|			<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('score_package_add')}','添加套餐',600,300,true,false,false,addbtn,'add',true);">添加套餐</a>|			<a href="{pigcms{:U('score_package_order')}">积分订单列表</a>		</ul>	</div>	<form name="myform" id="myform" action="" method="post">		<div class="table-list">			<table width="100%" cellspacing="0">				<colgroup>					<col/>					<col/>					<col/>					<col/>					<col width="180" align="center"/>				</colgroup>				<thead>					<tr>						<th>编号</th>						<th>套餐名</th>						<th>积分数</th>						<th>原价</th>						<th>价格</th>						<th>排序</th>						<th>状态</th>						<th>创建时间</th>						<th>操作</th>					</tr>				</thead>				<tbody>					<if condition="is_array($list['list'])">						<volist name="list.list" id="vo">							<tr>								<td>{pigcms{$vo.package_id}</td>								<td>{pigcms{$vo.name}</td>								<td>{pigcms{$vo.score}</td>                                <td>{pigcms{$vo.old_price}</td>                                <td>{pigcms{$vo.price}</td>								<td>{pigcms{$vo.sort}</td>								<td>									<if condition="$vo['status'] eq 0"><font color="red">关闭</font><elseif condition="$vo['status'] eq 1"/><font color="green">启用</font></if>								</td>                                <td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>								<td style="text-align: right;">									<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('score_package_edit',array('package_id'=>$vo['package_id']))}','编辑积分套餐',600,300,true,false,false,editbtn,'edit',true);">编辑</a>|									<a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.package_id}" url="{pigcms{:U('score_package_del')}">删除</a>							  	</td>							</tr>						</volist>						<tr><td class="textcenter pagebar" colspan="10">{pigcms{$list.pagebar}</td></tr>					<else/>						<tr><td class="textcenter red" colspan="10">列表为空！</td></tr>					</if>				</tbody>			</table>		</div>	</form></div><include file="Public:footer"/>